      "howto": "① 예측 탭에서 무역풍이 약해질 때의 변화를 먼저 예측해요.\n② 실험 탭: **무역풍의 세기** 슬라이더를 움직이거나 **엘니뇨·평상시·라니냐** 버튼을 눌러요.\n적도 태평양 단면에서 따뜻한 해수층, 수온 약층의 깊이, 해수면 높이, 상승 기류의 위치와 **동태평양 수온 편차**를 관찰해요.\n**실제 자료로 맞춰 보기**로 1997~98, 2015~16 엘니뇨와 2010~11, 2020~21 라니냐를 불러와 비교해요.\n③ 미션 탭의 도전 과제를 모두 달성해 보세요.",
