      "concept": "추진기 제작 기관은 자세 제어 추진기가 낸 충격량을 야드파운드법 단위(lbf·s)로 보고했다.\n항법 기관의 프로그램은 그 숫자를 국제단위계 단위(N·s)로 여기고 그대로 계산했다.\n실제 힘이 예측보다 약 4.45배 컸던 셈이어서, 작은 오차가 10개월 동안 쌓여 궤도가 화성 쪽으로 틀어졌다.\n궤도선은 계획(약 226 km)보다 훨씬 낮은 약 57 km 고도로 들어가 대기와의 마찰을 견디지 못했다.",
