      "concept": "위성은 ‘보낸 시각’과 ‘자기 위치’를 담은 신호를 보낸다.\n수신기는 신호가 도착한 시각과 비교해 걸린 시간을 구하고, 빛의 속력을 곱해 거리를 계산한다.\n위성 하나로는 원 위의 어딘가, 둘이면 두 점, 셋이면 한 점으로 위치가 정해진다(삼변측량).\n수신기 시계는 위성의 원자시계만큼 정확하지 않아 모든 거리가 같은 만큼 틀린다. 그래서 실제로는 네 개 이상의 위성으로 시계 오차까지 함께 구한다.",
      "inquiry": "위성을 하나만 썼을 때와 두 개를 썼을 때 조난자가 있을 수 있는 곳은 각각 어떤 모양인가요?\n신호 도착 시간이 1 ms 길게 측정되면 거리는 얼마나 길어지나요?\n시계 오차가 있는 라운드에서 원 세 개가 한 점에서 만나지 않는 까닭은 무엇일까요? 보정 슬라이더로 원이 한 점에 모이게 해 보세요.\n실제 GPS는 3차원 공간에서 위치를 구합니다. 시계 오차까지 구하려면 최소 몇 개의 위성이 필요할까요?",
      "added": "2026-10-14",
