      "status": "ready",
      "height": 0,
      "howto": "",
      "concept": "현대의 주기율표는 원소를 원자 번호(양성자 수) 순으로 나열하고, 성질이 비슷한 원소가 같은 세로줄(족)에 오도록 배열했다.\n같은 주기의 원소는 전자 껍질 수가 같고, 같은 족의 원소는 가장 바깥 껍질의 전자 수(원자가 전자 수)가 같다.\n원자가 전자는 화학 결합에 참여하므로, 원자가 전자 수가 같은 같은 족 원소는 화학적 성질이 비슷하다.\n18족 이외의 원소는 전자를 잃거나 얻어 18족 원소와 같은 전자 배치를 이루려 한다.",
      "inquiry": "리튬(Li)과 나트륨(Na)의 전자 배치를 비교하세요. 무엇이 같고 무엇이 다른가요?\n헬륨, 네온, 아르곤이 다른 원소와 거의 반응하지 않는 까닭을 전자 배치로 설명해 보세요.\n마그네슘(Mg)과 산소(O)는 각각 어떤 이온이 되기 쉬울까요? 직접 만들어 확인해 보세요.\n칼슘(Ca)은 4주기 원소입니다. 칼슘의 전자 껍질 수와 원자가 전자 수는 각각 몇인가요?",
