      "concept": "이온 결합 물질의 고체는 양이온과 음이온이 정전기적 인력으로 단단히 붙잡혀 있어 이동할 수 없다 → 전류가 흐르지 않는다.\n물에 녹으면 양이온과 음이온이 나뉘어 자유롭게 움직인다. 양이온은 (−)극, 음이온은 (+)극으로 이동하며 전류가 흐른다.\n설탕, 포도당 같은 공유 결합 물질은 물에 녹아도 전하를 띠지 않는 분자 상태로 흩어지므로 전류가 흐르지 않는다.\n구리 같은 금속은 자유 전자가 있어 고체 상태에서도 전류가 흐른다.",
