      "concept": "자유 낙하: 중력만 받아 속력이 1초마다 9.8 m/s씩 일정하게 빨라지는 운동이다(가속도 9.8 m/s², 방향 연직 아래).\n수평으로 던진 물체도 연직 방향으로는 자유 낙하와 똑같이 움직인다. 그래서 같은 높이에서 동시에 출발하면 동시에 떨어진다.\n수평 방향으로는 힘을 받지 않아 처음 속도 그대로 일정하게 움직인다(등속 운동).\n두 운동이 합쳐져 포물선 경로가 된다.",
