      "concept": "운동량 = 질량 × 속도. 질량이 클수록, 속도가 빠를수록 운동량이 크다.\n충격량 = 힘 × 힘이 작용한 시간 = 운동량의 변화량. 힘–시간 그래프 아래 넓이와 같다.\n같은 높이에서 떨어진 달걀이 멈출 때 받는 충격량은 같다. 하지만 충돌 시간이 길어지면 평균 힘이 작아진다(평균 힘 = 충격량 ÷ 충돌 시간).\n두 물체가 충돌하면 서로 같은 크기의 힘을 반대 방향으로 같은 시간 동안 주고받으므로 받은 충격량의 크기가 같다. 질량이 작은 쪽의 속도가 더 크게 변한다.",
