      "concept": "지질 시대는 지층에서 나오는 화석과 생물계의 큰 변화(대멸종 등)를 기준으로 나눈다.\n선캄브리아 시대는 전체의 약 88 %를 차지하지만 단단한 껍데기를 가진 생물이 적어 화석이 드물다.\n표준 화석은 특정 시대에만 살아 지층의 시대를 알려 주고, 시상 화석은 산호처럼 당시의 환경을 알려 준다.",
      "inquiry": "지구 역사를 하루로 줄이면 인류는 몇 시 몇 분쯤 나타났을까요?\n선캄브리아 시대의 화석이 드문 까닭은 무엇일까요?\n삼엽충 화석과 산호 화석이 함께 나온 지층은 어떤 환경에서 쌓였을까요?\n고생대와 중생대, 중생대와 신생대의 경계에서는 어떤 일이 있었을까요?",
      "added": "2026-10-14",
      "updated": "2026-10-14"
