      "concept": "대멸종은 짧은 기간에 많은 생물 종이 함께 사라지는 사건으로, 지질 시대를 나누는 기준이 된다.\n대멸종의 원인으로 소행성 충돌, 대규모 화산 활동, 기후·해수면 변화, 해양의 산소 부족 등이 제시된다.\n대멸종 뒤 살아남은 생물이 비어 있는 환경으로 퍼져 나가 새로운 종이 많이 생겨났다. 중생대 말 이후 포유류가 번성한 것이 그 예이다.",
      "inquiry": "다섯 번의 대멸종 중 가장 많은 생물이 사라진 것은 언제인가요? 그 원인은 무엇으로 추정되나요?\n대멸종 뒤 생물다양성 그래프는 어떻게 변하나요? 그 까닭은?\n이리듐 농축층과 칙술루브 충돌구는 어떤 가설을 뒷받침하나요?\n하나의 증거가 두 가설을 모두 설명할 수 있을 때, 가설의 타당성은 어떻게 판단해야 할까요?",
