      "status": "ready",
      "height": 0,
      "howto": "",
      "concept": "산은 물에 녹아 수소 이온(H⁺)을 내놓는다. 마그네슘 같은 금속과 반응해 수소 기체, 탄산 칼슘과 반응해 이산화 탄소 기체를 낸다. BTB 용액을 노란색으로 바꾼다.\n염기는 물에 녹아 수산화 이온(OH⁻)을 내놓는다. BTB 용액을 파란색, 페놀프탈레인 용액을 붉은색으로 바꾼다. 단백질을 녹이는 성질이 있어 만지면 미끈거린다.\n산과 염기의 수용액은 모두 이온이 있어 전류가 흐른다.",
      "inquiry": "묽은 염산과 아세트산 수용액이 공통으로 보이는 성질은 무엇인가요? 그 까닭은?\n마그네슘 조각을 넣었을 때 기체가 발생하는 용액은 어떤 것인가요? 이 기체는 무엇일까요?\n설탕물에서 전류가 흐르지 않는 까닭은 무엇일까요?\n미지 용액을 감별할 때 가장 효율적인 시험 순서를 정해 보세요.",
      "added": "2026-10-14",
