      "concept": "발열 반응: 반응이 일어날 때 에너지를 방출해 주위의 온도가 높아진다. (예: 산화 칼슘과 물의 반응, 철의 산화, 연소, 중화 반응)\n흡열 반응: 반응이 일어날 때 에너지를 흡수해 주위의 온도가 낮아진다. (예: 질산 암모늄이 물에 녹을 때, 광합성, 열분해)\n넣는 물질의 양이 많을수록 출입하는 열의 양도 많아진다.\n반응이 빠르면 온도가 빨리 변하고, 느리면 오래 유지된다. 소금물과 활성탄은 철이 산화되는 반응을 빠르게 한다.",
      "inquiry": "발열 도시락에 산화 칼슘을, 손난로에 철가루를 주로 쓰는 까닭을 그래프 모양과 관련지어 설명해 보세요.\n질산 암모늄을 넣었을 때 온도가 낮아지는 까닭을 에너지의 출입으로 설명해 보세요.\n철가루만 넣었을 때와 소금물·활성탄을 함께 넣었을 때 그래프는 어떻게 다른가요?\n같은 물질을 두 배로 넣으면 온도 변화는 어떻게 되나요? 그 까닭은 무엇인가요?\n내가 설계한 제품의 장점과 개선할 점을 안전성, 비용, 환경 측면에서 평가해 보세요.",
