      "status": "ready",
      "height": 0,
      "howto": "",
      "concept": "생산자는 광합성으로 빛에너지를 유기물 속 화학 에너지로 바꾼다.\n먹이 관계를 따라 에너지가 1차, 2차, 3차 소비자로 전달된다. 먹이사슬이 얽혀 먹이그물을 이룬다.\n각 영양단계는 받은 에너지의 대부분을 생명 활동에 쓰고 열로 내보내며, 일부(약 10 %)만 다음 단계로 전달한다.\n그래서 상위 영양단계로 갈수록 에너지양, 개체수, 생물량이 줄어드는 생태피라미드를 이룬다.\n에너지는 순환하지 않고 한 방향으로 흐르다가 결국 열로 생태계를 빠져나간다.",
      "inquiry": "이 먹이그물에서 매는 몇 차 소비자인가요? 먹이사슬에 따라 답이 여러 개일 수 있는 까닭은 무엇인가요?\n들쥐를 없애면 어떤 생물이 가장 큰 영향을 받나요? 먹이를 대신할 수 있는 생물과 없는 생물을 구분해 보세요.\n메뚜기를 없애 보세요. 개구리가 사라지는 까닭과, 그 영향이 뱀에게 어떻게 이어지는지 설명해 보세요.\n에너지 효율이 10 %일 때 최종 소비자에게 전달되는 에너지는 생산자의 몇 %인가요?\n먹이사슬의 단계가 보통 4~5단계를 넘지 않는 까닭을 생태피라미드로 설명해 보세요.",
