      "desc": "태양 중심부에서는 수소 원자핵이 융합해 헬륨 원자핵이 되며, 이때 줄어든 질량이 에너지로 바뀝니다. 온도를 바꾸어 핵융합을 일으켜 보고, 우리가 쓰는 에너지 가운데 무엇이 태양에서 왔는지 가려내 보세요.",
