      "status": "ready",
      "height": 0,
      "howto": "",
      "concept": "코일을 통과하는 자기장이 변할 때 코일에 전류가 흐르는 현상을 전자기 유도라 하고, 이 전류를 유도 전류라고 한다.\n자석을 빠르게 움직일수록, 자석이 셀수록, 코일을 많이 감을수록 유도 전류가 세다.\n자석을 넣을 때와 뺄 때, N극과 S극일 때 유도 전류의 방향이 반대이다.\n유도 전류는 자석의 움직임을 방해하는 방향으로 흐른다(가까워지면 밀어내고, 멀어지면 끌어당김).\n발전기는 코일 속에서 자석(또는 자석 사이에서 코일)을 회전시켜 운동 에너지를 전기 에너지로 바꾼다. 회전하므로 방향이 계속 바뀌는 교류가 만들어진다.",
      "inquiry": "자석을 코일 속에 넣은 채 가만히 두면 검류계 바늘은 어떻게 되나요? 그 까닭은 무엇인가요?\n자석을 넣을 때와 뺄 때 바늘이 움직이는 방향을 비교해 보세요.\n유도 전류를 세게 하는 방법 세 가지를 실험으로 확인하고 정리해 보세요.\n손발전기에서 켜진 전등이 늘어날수록 손잡이를 돌리기가 힘들어지는 까닭을 에너지 전환으로 설명해 보세요.\n발전소마다 발전기를 돌리는 에너지원은 다릅니다. 화력, 수력, 풍력 발전에서 발전기를 돌리는 것은 각각 무엇인가요?",
