      "concept": "화력·원자력 발전: 연료의 화학 에너지나 핵에너지로 물을 끓여 증기로 터빈을 돌린다. 원자력은 출력을 자주 바꾸기 어려워 기저 부하를 맡는다.\nLNG 발전은 출력을 빠르게 바꿀 수 있어 수요가 몰리는 시간(첨두 부하)을 맡는다.\n태양광·풍력은 연료가 필요 없고 이산화 탄소를 배출하지 않지만, 날씨에 따라 발전량이 달라진다.\n양수 발전은 남는 전기로 물을 높은 곳에 올려 두었다가 필요할 때 흘려보내 발전하는 일종의 에너지 저장 장치이다.\n발전소에서 만든 전기는 변압기로 전압을 높여 송전하고, 가정 가까이에서 다시 전압을 낮춘다. 전압이 높을수록 전류가 작아 송전선에서 열로 잃는 전력이 줄어든다.",
