      "concept": "에너지는 한 형태에서 다른 형태로 전환되며, 전환 전후 에너지의 총량은 일정하다(에너지 보존 법칙).\n그러나 전환 과정에서 일부는 열, 소리 등 다시 쓰기 어려운 형태로 흩어진다.\n에너지 효율(%) = 유용하게 쓰인 에너지 ÷ 공급한 에너지 × 100. 효율은 100 %가 될 수 없다.\n열기관은 연료의 에너지 중 일부만 일로 바꾸고 나머지는 열로 방출한다.\n효율이 높은 기기를 쓰면 같은 일을 하면서 에너지와 비용, 이산화 탄소 배출을 줄일 수 있다.",
      "inquiry": "백열전구와 LED 전구에 같은 전기 에너지를 공급했을 때 빛에너지와 열에너지의 비율을 비교해 보세요.\n휘발유 자동차와 전기 자동차의 효율이 크게 다른 까닭은 무엇일까요?\n에너지가 보존되는데도 ‘에너지를 절약해야 한다’고 말하는 까닭을 설명해 보세요.\n리모델링 게임에서 가장 ‘가성비’가 좋았던 선택은 무엇이었나요? 비용과 절약량으로 근거를 들어 보세요.\n학교에서 에너지 효율을 높일 수 있는 방법을 세 가지 제안해 보세요.",
