      "status": "ready",
      "height": 0,
      "howto": "",
      "concept": "빅데이터는 기존 방법으로는 다루기 어려울 만큼 방대하고 복잡한 데이터의 집합이다. 크기(Volume), 속도(Velocity), 다양성(Variety)이 특징이다.\n수치뿐 아니라 글, 영상, 위치 정보 등 다양한 형태의 데이터를 종합해 분석하면 복잡한 문제의 패턴을 빠르게 찾을 수 있다.\n기상 예측, 감염병 확산 예측, 교통 정보, 맞춤형 추천, 과학 연구 등에 쓰인다.\n두 데이터가 함께 변한다고(상관관계) 한쪽이 다른 쪽의 원인(인과 관계)이라고 단정할 수 없다. 공통 원인이 숨어 있을 수 있다.\n데이터가 한쪽으로 치우치거나(편향), 개인 정보가 드러나지 않도록 주의해야 한다.",
      "inquiry": "아이스크림 판매량과 가장 관계가 깊은 데이터는 무엇인가요? 산점도와 r 값으로 설명해 보세요.\n아이스크림 판매량과 물놀이 사고가 함께 늘어나는 까닭은 무엇일까요? 숨은 공통 원인을 찾아보세요.\n음의 상관관계를 보이는 데이터 쌍을 하나 찾고, 그 관계가 생기는 까닭을 추론해 보세요.\n데이터를 한 지역이나 한 계절에서만 모으면 어떤 문제가 생길 수 있나요?\n내가 매일 만드는 데이터(위치, 검색 기록 등)가 어떻게 쓰일 수 있으며, 무엇을 주의해야 할지 토의해 보세요.",
      "added": "2026-10-14",
