      "status": "ready",
      "height": 0,
      "howto": "",
      "concept": "사물 인터넷은 사물에 센서와 통신 장치를 달아 인터넷으로 정보를 주고받는 기술이다.\n센서가 주변 환경(온도, 빛, 기체 농도, 움직임 등)을 측정해 데이터로 바꾼다.\n데이터는 네트워크를 통해 제어 장치(또는 클라우드)로 전달되고, 정해진 규칙이나 인공지능이 판단한다.\n판단 결과에 따라 에어컨, 환기 장치, 조명 같은 기기(작동기)가 자동으로 움직인다.\n스마트 홈, 스마트 팜, 스마트 시티처럼 삶을 편리하게 하고 에너지를 아끼지만, 해킹이나 개인 정보 유출에 대비해야 한다.",
      "inquiry": "규칙을 하나도 켜지 않았을 때 교실은 어떻게 변하나요? 어떤 값이 먼저 기준을 넘었나요?\n‘CO₂가 높으면 창문 열기’ 규칙은 오후에 어떤 문제를 일으켰나요? 이를 해결하려면 어떤 센서 정보를 함께 써야 할까요?\n‘사람이 없으면 기기 끄기’ 규칙은 에너지 사용량에 어떤 영향을 주었나요?\n내가 만든 규칙에서 쓰인 센서와 작동기를 짝지어 정리해 보세요.\n우리 학교나 집에 사물 인터넷을 적용한다면 어떤 문제를 해결하고 싶나요? 해킹, 개인 정보 같은 문제는 어떻게 대비할까요?",
