      "height": 0,
      "howto": "① 예측 탭에서 개기 월식 때 달이 어떻게 보일지 골라요. 아래 **우리나라에서 본 실제 월식** 버튼으로 실제 월식의 길을 불러올 수 있어요.\n② 실험 탭: **달이 지나는 길** 슬라이더를 바꾸거나 **개기·부분·반영식** 버튼을 눌러요.\n**월식 진행**을 누르거나 **시간** 슬라이더(또는 그림 속 달 끌기)로 달을 움직이면, 아래에 **지구에서 본 달**과 **달의 밝기 그래프**가 그려져요.\n달의 가장자리가 본그림자 경계에 닿는 순간마다 **● 지금 접촉!**을 눌러 접촉 시각(U1~U4)을 기록하고 정확도를 확인해요.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
      "concept": "**월식**은 달이 지구의 그림자 속으로 들어가는 현상으로, 망(음력 15일) 무렵 태양-지구-달이 일직선에 놓일 때 일어납니다.\n달 전체가 본그림자에 들어가면 **개기 월식**, 일부만 들어가면 **부분 월식**, 반그림자만 지나면 **반영식**입니다.\n월식은 밤인 지역 어디에서나 같은 모습으로 관측됩니다.",
      "inquiry": "개기 월식 때 달이 붉게 보이는 까닭은?\n일식보다 월식을 관측할 수 있는 지역이 넓은 까닭은?",
      "added": "2026-10-27",
