      "status": "ready",
      "height": 0,
      "howto": "① 예측 탭에서 개기 일식이 보이는 곳에서 1000 km 떨어진 곳은 어떻게 보일지 먼저 골라요.\n② 실험 탭: **달의 거리**·**관측 위치**·**진행** 슬라이더를 바꾸며 옆모습과 관측자가 본 하늘을 비교해요. **가까운 달·먼 달** 버튼으로 개기·금환 일식을 바꿔요.\n아래 **그림자 띠 지도**에서 노란 관측자를 **끌어** 옮기면 본그림자 띠(폭 수백 km 이하) 안팎에서 보이는 일식이 어떻게 달라지는지 알 수 있어요.\n**▶ 일식 진행**을 누르면 시간에 따른 태양 밝기가 **밝기 곡선**으로 기록돼요. 관측 위치를 바꿔 여러 번 그려 비교해요.\n**실제 일식 불러오기**(① 예측 탭 아래)로 2024년 개기 일식, 2023년 금환 일식, 2020년 우리나라의 부분 일식, 2035년 한반도 개기 일식(예정)을 살펴봐요.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
      "concept": "**일식**은 달이 태양을 가리는 현상으로, 삭(음력 1일) 무렵 태양-달-지구가 일직선에 놓일 때 일어납니다.\n달이 지구에 가까워 태양보다 크게 보이면 **개기 일식**, 멀어서 작게 보이면 **금환 일식**이 일어납니다.\n달의 본그림자 밖, 반그림자 안에서는 **부분 일식**이 관측됩니다.",
      "inquiry": "금환 일식이 일어날 때 달은 지구에서 가까울까, 멀까?\n같은 일식이라도 지역에 따라 다르게 관측되는 까닭은?",
      "added": "2026-10-27",
