      "id": "retrograde-motion",
      "title": "행성의 겉보기 운동",
      "desc": "위는 지구 시점(별자리 배경), 아래는 우주 시점이에요. 위치를 기록하며 역행을 찾아봐요.",
      "file": "sims/astro/retrograde-motion.html",
