      "status": "ready",
      "height": 0,
      "howto": "① 예측 탭에서 화성이 역행할 때 지구와의 거리를 먼저 예측해요.\n② 실험 탭: **행성 고르기**로 수성~토성을 고르고 **속도** 슬라이더로 시간 흐름을 조절해요. **멈춤**과 **+10일**로 원하는 순간을 찾아요.\n위(지구 시점)의 별자리 띠를 누르거나 **★ 지금 위치 기록**을 눌러 행성 위치를 찍으면 역행 고리가 그려져요.\n아래(우주 시점)에서 지구와 행성의 위치를, 오른쪽 아래 **거리 그래프**에서 역행할 때 거리가 어떻게 되는지 확인해요. 유에서 다음 유까지의 **역행 기간**은 저절로 재어져요.\n**실제 관측 자료와 비교**(① 예측 탭 아래)로 2022~23·2024~25 화성 역행 날짜와 행성별 역행 기간을 모형과 비교해요.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
      "concept": "행성은 별자리 사이를 대부분 서 → 동으로 이동(**순행**)하지만, 때때로 동 → 서로 이동(**역행**)합니다. 방향이 바뀌는 순간을 **유**라고 합니다.\n외행성은 지구가 행성을 추월하는 **충** 무렵, 내행성은 **내합** 무렵에 역행합니다.\n역행은 공전 속도가 다른 지구에서 행성을 관측하기 때문에 나타나는 겉보기 운동입니다.",
      "inquiry": "화성이 역행할 때 지구와 화성의 거리는 가까울까, 멀까?\n외행성 중 역행 기간이 가장 긴 행성과 짧은 행성을 비교해 보자.",
      "added": "2026-10-27",
