      "status": "ready",
      "height": 0,
      "howto": "① 예측 탭에서 반지름 2배·온도 절반인 별의 광도를 먼저 예측해요.\n② 실험 탭: **반지름**과 **표면 온도** 슬라이더를 바꾸면 별의 크기·색과 광도 막대가 바뀌어요. 태양·확인 문제 별·작고 뜨거운 별·크고 차가운 별 버튼으로 예시를 불러와요.\n오른쪽 **H-R도**에 만든 별(★)이 나타나요. H-R도를 **직접 끌면** 그 온도·광도에 맞는 반지름이 계산돼요. 점선은 반지름이 같은 별을 이은 선이에요.\n**실제 별 만들기** 버튼으로 시리우스 A·B, 프록시마, 아르크투루스, 알데바란, 리겔의 반지름과 온도를 넣어 광도를 계산하고 H-R도에서 위치를 비교해요.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
      "concept": "별의 **광도**는 별이 단위 시간에 방출하는 총에너지로, L = 4πR²σT⁴입니다.\n태양과 비교하면 L/L☉ = (R/R☉)² × (T/T☉)⁴이므로, 온도가 낮아도 반지름이 매우 크면 광도가 클 수 있습니다.",
      "inquiry": "반지름이 태양의 2배이고 온도가 같은 별의 광도는 태양의 몇 배일까?\n차갑지만 매우 밝은 별이 존재할 수 있는 까닭은?",
      "added": "2026-10-27",
