      "height": 0,
      "howto": "① 예측 탭에서 수소 흡수선이 가장 강한 별을 먼저 골라요.\n② 실험 탭: **표면 온도** 슬라이더를 움직이거나 **그래프를 직접 끌어** 흡수선 세기 곡선·막대와 별의 색을 관찰해요.\n그래프 아래 **별의 스펙트럼**에서 온도에 따라 검은 흡수선이 짙어지고 옅어지는 모습을 확인해요.\n**미지의 별 문제**를 누르면 미지의 별 스펙트럼과 막대가 나와요. 온도를 맞춘 뒤 **판정하기**로 분광형을 맞혀 보고, **정답 보기**로 확인해요.\n**실제 별의 분광형** 버튼으로 나오스(O)부터 베텔게우스(M)까지 실제 별의 온도와 흡수선을 비교해요.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
      "concept": "별의 스펙트럼에 나타나는 흡수선의 종류와 세기는 표면 온도에 따라 달라집니다.\n이를 기준으로 별을 O, B, A, F, G, K, M형으로 분류하며(**분광형**), O형으로 갈수록 온도가 높습니다.\n예를 들어 수소 흡수선(H Ⅰ)은 A형에서, 이온화된 칼슘(Ca Ⅱ)은 G~K형에서 강하게 나타납니다.",
      "inquiry": "태양(G형)의 스펙트럼에서 가장 강하게 나타나는 흡수선은?\n별의 화학 조성이 비슷한데도 흡수선의 세기가 다른 까닭은?",
