      "howto": "① 예측 탭에서 CNO 순환 반응 뒤 탄소(¹²C)가 어떻게 될지 골라요. 아래 **실제 별에서는?** 버튼으로 태양의 실제 관측 사실을 확인해요.\n② 실험 탭: **중심부 온도** 슬라이더나 **태양·무거운 별** 버튼으로 온도를 바꾸며 그래프에서 우세한 반응을 확인해요.\n**반응 실험대**에서 **p-p 연쇄 반응**을 골라 ¹H + ¹H, ²H + ¹H, ³He + ³He 반응을 순서대로 일으켜 헬륨을 만들어요.\n**CNO 순환 반응**을 골라 **양성자 붙잡기**와 **β⁺ 붕괴 기다리기** 중 알맞은 것을 골라 ¹²C → ¹³N → ¹³C → ¹⁴N → ¹⁵O → ¹⁵N → ¹²C 한 바퀴를 완성해요.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
      "concept": "주계열성 중심부의 수소 핵융합에는 **양성자·양성자 연쇄 반응(p-p 반응)**과 **탄소·질소·산소 순환 반응(CNO 순환 반응)**이 있습니다.\n중심부 온도가 약 1800만 K보다 낮으면 p-p 반응, 높으면 CNO 순환 반응이 우세합니다.\n태양(약 1500만 K)에서는 p-p 반응이 우세합니다.",
