      "concept": "질량이 작은 별은 적색 거성 → 행성상 성운을 거쳐 중심핵이 **백색 왜성**으로 남습니다.\n질량이 큰 별은 초거성 → 초신성 폭발을 거쳐, 중심핵 질량이 약 1.4~3 M☉이면 **중성자별**, 약 3 M☉보다 크면 **블랙홀**이 됩니다.",
