      "howto": "① 예측 탭에서 핵융합 뒤 질량이 어떻게 될지 먼저 골라요.\n② 실험 탭: **중심부 온도**를 정하고 **핵융합!**을 눌러요. 온도가 낮으면 양성자끼리 밀어내 튕겨 나가고, 충분히 높으면 헬륨 원자핵이 되며 저울이 기울어요.\n**수소의 양** 슬라이더(1번·1 g·1 kg·태양 1초)를 바꾸며 방출 에너지를 비교하고, 아래 **에너지 눈금**에서 크기 차이를 확인해요.\n**실제 태양에 적용하기**에서 태양 중심 온도, 태양이 1초에 잃는 질량, 태양의 수명을 계산해 봐요.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
