      "howto": "① 예측 탭에서 우주 배경 복사가 언제 퍼져 나간 빛인지 골라 봐요.\n왼쪽 위: 카드를 하나 누른 뒤 알맞은 상자(**증거·한계·해결**)를 눌러 분류해요.\n왼쪽 아래 **우주 역사 띠**: 사건 카드(급팽창·헬륨 원자핵 생성·우주 배경 복사 방출·가속 팽창 관측)를 끌어 알맞은 때에 놓아요.\n② 실험 탭에서 진행 상황을 보고, **연표**(1929·1948·1965·1981·1998) 버튼으로 증거가 발견된 순서를 확인해요.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
      "concept": "빅뱅 우주론의 증거: **우주 배경 복사**, **수소 : 헬륨 질량비 ≈ 3 : 1**.\n빅뱅 우주론의 한계: **평탄성 문제**, **지평선 문제**.\n이 한계는 **급팽창 우주론**이 해결했으며, 이후 Ia형 초신성 관측으로 **가속 팽창 우주론**이 등장했습니다.",
      "inquiry": "빅뱅 우주론의 두 가지 증거를 설명해 보자.\n급팽창 우주론은 지평선 문제를 어떻게 해결했을까?",
      "added": "2026-10-27",
