      "status": "ready",
      "height": 0,
      "howto": "① 예측 탭에서 현재 팽창 속도가 같을 때 나이가 가장 많은 우주를 골라 보고, [실험하러 가기]를 눌러 확인합니다.\n② 실험 탭: **닫힌·평탄·열린·가속 팽창 우주** 버튼으로 표시할 모형을 켜고 끕니다. **다시 그리기**를 누르면 곡선이 과거부터 미래까지 다시 그려집니다.\n그래프를 끌거나 **시간 커서** 슬라이더를 움직이면, 그때 각 우주의 **크기·적색 편이·우주 배경 복사 온도**와 은하 사이 간격이 아래 그림에 나타납니다.\n**나만의 우주**에서 물질 밀도와 암흑 에너지 밀도를 바꿔 새 우주 모형을 만들고, **허블 상수**를 바꿔 시간 눈금과 우주의 나이가 어떻게 달라지는지 봅니다.\n① 예측 탭 아래 **실제 관측** 버튼(플랑크 위성 2018, 1998 초신성 관측, 우주 배경 복사)으로 실제 우주를 모형에 넣어 비교합니다.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
      "concept": "우주의 밀도가 임계 밀도보다 크면 **닫힌 우주**(팽창하다 수축), 같으면 **평탄 우주**, 작으면 **열린 우주**(계속 팽창)입니다.\n관측에 따르면 현재 우주는 거의 평탄하며, 약 60억 년 전부터 **가속 팽창**하고 있습니다(암흑 에너지).\n같은 현재 팽창 속도라도 가속 팽창 우주는 초기에 천천히 팽창해 나이가 더 많습니다.",
