      "status": "ready",
      "height": 0,
      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **수축 정도**, **원시 태양 밝기**, **원반의 고체 양** 슬라이더를 움직여요.\n**① 성운의 수축과 회전**, **② 원반 속 행성 만들기**, **💥 초신성 충격파**, **↺ 처음으로**, **▶ 시작**, **↺ 새 원반**, **⏩ 3배속**, **🪐 실제 행성** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
      "concept": "**성운 수축·회전**: 반지름이 줄수록 각운동량 보존으로 회전이 빨라지고 납작한 원반이 돼요.\n**원시 태양**: 중심이 수축하며 뜨거워지고, 약 1000만 K에서 수소 핵융합이 시작돼요.\n**미행성체**: 티끌이 응축·충돌해 수 km 크기가 돼요. 눈선 바깥은 얼음까지 고체가 돼요.\n**원시 행성**: 미행성체가 충돌·집적해 자라고, 눈선 바깥의 큰 핵은 성운 가스를 끌어당겨요.\n**태양계 천체**: 안쪽은 지구형, 바깥은 목성형 행성, 남은 미행성체는 소행성·혜성이 돼요.",
      "inquiry": "회전하던 태양계 성운이 중력으로 수축하면, 회전 속도는 어떻게 될까요?\n성운을 끝까지 수축시켜 중심에서 수소 핵융합이 시작되게 해 보세요.\n② 단계에서 원시 태양을 밝게 해 눈선을 4 AU 바깥으로 옮겨 보세요.",
      "added": "2026-10-27",
