      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **화산 활동**, **풍화 작용**, **태양 밝기** 슬라이더를 움직여요.\n**▶ 시간 흐르기**, **🌋 거대 화산 분출**, **현재 지구**, **❄ 원생 누대 말 조건**, **↺ 처음으로** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
      "concept": "**온난한 지구**: 화산이 CO₂를 내놓고, 풍화·바다가 CO₂를 흡수해 석회암으로 쌓여 균형을 이뤄요.\n**냉각 시작**: 얼음이 넓어지면 반사율이 커져 더 식어요(얼음이 얼음을 부름).\n**얼음덩어리 지구**: 얼음에 덮여 풍화·해양 흡수가 멈추고, 화산 CO₂만 계속 쌓여요.\n**탈출·온실 지구**: CO₂ 온실 효과로 얼음이 녹으면 반사율이 줄어 급격히 따뜻해지고, 빠른 풍화로 석회암이 쌓여요.",
      "inquiry": "지구 전체가 얼음으로 덮이면, 대기 중 CO₂는 어떻게 될까요?\n지구 전체를 얼음으로 덮어 보세요.\n얼음덩어리 지구에서 탈출해 보세요. (얼음 50% 미만)",
