      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **남세균 광합성**, **철(Fe²⁺) 공급** 슬라이더를 움직여요.\n**▶ 시간 흐르기**, **⏩ 3배속**, **↺ 38억 년 전** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
      "concept": "**산소 없는 바다**: 해저 화산에서 철 이온(Fe²⁺)이 녹아 들고, 강한 자외선이 지표에 쏟아져요.\n**호상철광층**: 약 35억 년 전 남세균이 만든 산소가 철과 반응해 산화 철로 가라앉아요. 철층과 규질층이 번갈아 쌓여 띠가 돼요.\n**대기 산소 증가**: 바닷속 철이 바닥나면 남는 산소가 대기로 나가요. 그래서 약 20억 년 전 이후 호상철광층은 거의 없어요.\n**오존층·육지 진출**: 오존층이 자외선을 막자 생물이 육지로 올라오고, 생물과 지구 환경이 함께 변해요(공진화).",
      "inquiry": "남세균이 산소를 만들기 시작하면, 대기 중 산소는 곧바로 늘어날까요?\n호상철광층의 철 띠를 12개 이상 쌓아 보세요.\n24억 년 전보다 먼저 대기 산소를 1% 넘겨 보세요.",
