      "concept": "**뜨거운 플룸**: 맨틀과 외핵의 경계에서 기둥 모양으로 올라오는 고온의 상승류\n**차가운 플룸**: 섭입한 판이 쌓였다가 하부 맨틀로 내려가는 저온의 하강류 (밀도 큼)\n지진파는 **뜨거운 곳에서 느리고, 차가운 곳에서 빨라요** → 지진파 단면 영상법\n판 구조론은 지표의 판 운동을, 플룸 구조론은 **맨틀 전체**의 큰 움직임을 설명해요. 뜨거운 플룸 위에 열점이 생겨요.",
