      "concept": "**해안선 모양**: 남아메리카 동해안과 아프리카 서해안이 꼭 맞아요.\n**지질 구조의 연속성**: 바다 건너 대륙의 산맥과 지층이 이어져요.\n**화석 분포**: 바다를 건널 수 없는 생물의 화석이 여러 대륙에서 나와요.\n**빙하 흔적**: 고생대 말 빙하가 긁은 자국이 한 중심에서 퍼져 나가요.",
