      "height": 0,
      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **판의 속도**, **판의 방향**, **과거 방향**, **과거 속도**, **최근 방향**, **최근 속도** 슬라이더를 움직여요.\n**자유 실험**, **실제 역사 8000만 년**, **🧭 열도 복원**, **▶ 시간 흐르기**, **⏩ 4배속**, **↺ 바다 비우기**, **🌋 열도 만들기**, **🎲 새 문제** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
      "concept": "맨틀 깊은 곳에서 올라온 **뜨거운 플룸**이 판 아래 한곳에서 마그마를 만들어요 → **열점**\n열점은 판이 움직여도 위치가 거의 변하지 않아요.\n열점에서 생긴 섬은 판과 함께 이동하고, 그 자리에 새 섬이 생겨요.\n열점에서 멀수록 섬이 **오래되고**, 침식·침강해 환초·해산이 돼요.\n판의 속도 = 섬까지 거리 ÷ 섬의 나이",
      "inquiry": "열점에서 멀리 떨어진 화산섬일수록 나이는 어떨까요?\n섬을 눌러 거리 ÷ 나이로 판의 속도를 구해 보세요.\n자유 실험에서 판의 방향을 30° 이상 바꿔 꺾인 열도를 만들어 보세요.",
