      "status": "ready",
      "height": 0,
      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **탐사선 위치** 슬라이더를 움직여요.\n**📡 음파 쏘기**, **🚢 자동 측정**, **🗺 새 해역**, **🔍 판독 시작** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
      "concept": "탐사선 바닥의 장치가 아래로 **음파**를 쏴요.\n음파는 해저면에서 반사되어 되돌아와요.\n왕복 시간 t를 재면 **수심 = 1500 m/s × t ÷ 2**\n여러 곳을 재어 이으면 해저 지형 단면이 돼요. 제2차 세계 대전 뒤 이 방법으로 **해령·해구·열곡**이 밝혀졌고, 해양저 확장설의 바탕이 됐어요.",
      "inquiry": "음파를 쏜 뒤 8초 만에 반사파가 돌아왔어요. 바닷속 음속이 1500 m/s라면 수심은?\n음파를 10번 이상 쏘아 해저 단면을 그려 보세요.\n수심 7 km보다 깊은 곳(해구)을 찾아 측정해 보세요.",
