      "concept": "**유리질**: 매우 빨리 식어 결정이 생기지 못함 (흑요석)\n**세립질**: 지표 부근에서 빨리 식어 결정이 작음 (현무암·유문암)\n**조립질**: 깊은 곳에서 천천히 식어 결정이 큼 (화강암·반려암)\n**반상**: 깊은 곳에서 자란 큰 반정 + 지표에서 굳은 작은 석기 (안산암)",
