      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **지각 두께 d**, **지각 V₁**, **맨틀 V₂**, **나누는 위치** 슬라이더를 움직여요.\n**원리 탐구**, **포항 지진 (2019)**, **🎯 미지의 지각**, **💥 지진 발생**, **✍ 직선 손으로 긋기**, **🎲 새 지역**, **확인** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
