      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **풍향**, **풍속** 슬라이더를 움직여요.\n**북반구**, **남반구**, **🎲 문제**, **🌬 이 바람으로 결정** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
      "concept": "표면 해수는 전향력 때문에 북반구에서 풍향의 **오른쪽 약 45°**로 흘러요.\n점성으로 움직임이 아래로 전달되며, 깊을수록 더 오른쪽으로 치우치고 느려져요(**에크만 나선**).\n표층과 정반대로 흐르는 깊이까지가 **마찰층(에크만층)**이에요.\n마찰층 전체의 평균 이동은 북반구에서 풍향의 **오른쪽 직각**, 남반구에서 **왼쪽 직각**(**에크만 수송**)\n수송이 먼바다로 → 연안 해수면 낮아짐 → 찬물이 올라옴(**용승**), 해안 쪽으로 → **침강**",
      "inquiry": "북반구에서 남풍(남→북)이 계속 불면, 에크만 수송은 어느 쪽으로 일어날까요?\n기본 해역(캘리포니아 연안)에 용승을 일으켜 보세요.\n남반구로 바꿔 에크만 나선이 어떻게 달라지는지 보세요.",
