      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **파장 L**, **수심 h**, **바람 세기** 슬라이더를 움직여요.\n**① 물 입자 운동**, **② 바다에서 해안까지**, **🌊 속도 계산**, **심해파 예**, **전이파 예**, **천해파 예**, **🦆 오리 인형**, **🎲 문제** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
      "concept": "**풍랑**: 바람 부는 곳 · 마루가 뾰족, 파장·주기 짧음\n**너울**: 바람 해역을 벗어남 · 마루가 둥글고 규칙적, 파장 김\n**연안 쇄파**: 얕은 해안 · 느려지고 높아져 부서짐\n해파는 물 입자가 이동하지 않고 **에너지만** 전달해요.",
      "inquiry": "파장이 같은 심해파가 수심 100 m에서 200 m인 곳으로 가면 속도는 어떻게 될까요?\n파장·수심을 바꿔 천해파를 만들어 보세요.\n전이파를 만들어 보세요.",
