      "concept": "**쓰나미(지진 해일)**: 해저 지진·화산으로 해수면 높이가 급변해 생겨요. 파장이 수백 km라 **천해파** → 속도 √(gh)\n깊은 바다에서는 빠르고 파고가 낮지만, 얕은 해안에서 **느려지고 파고가 높아져** 큰 피해를 줘요.\n**폭풍 해일**: 태풍의 낮은 기압(1 hPa ↓ → 약 1 cm ↑)과 강한 바람이 바닷물을 해안으로 밀어 생겨요.\n**만조**와 겹치거나 **만**처럼 폐쇄된 해역에서 더 강해져요.",
