      "concept": "**A → B**: 불포화 공기가 상승 → 건조 단열 감률(10 ℃/km)로 냉각, 이슬점은 2 ℃/km 감소\n**B**(상승 응결 고도): 기온 = 이슬점 → 포화, 구름 생성\n**B → C**: 습윤 단열 감률(5 ℃/km)로 냉각, 비가 내려 수증기를 잃어요.\n**C → D**: 하강하며 단열 압축 → 건조 단열 감률로 승온\nD는 A보다 **기온이 높고 이슬점이 낮은** 고온 건조한 바람 → **푄** (예: 높새바람)",
