      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **원판 회전**, **구슬 속력**, **위도**, **시간 흐름** 슬라이더를 움직여요.\n**① 회전 원판**, **② 푸코 진자와 위도**, **↺ 반시계 (북반구)**, **● 구슬 굴리기**, **종이 바꾸기**, **🎯 사격장 (5발)**, **북극**, **서울** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
      "concept": "회전하는 지구 위의 관찰자에게 움직이는 물체는 **북반구 오른쪽**, **남반구 왼쪽**으로 휘어 보여요.\n운동 방향에 수직으로 작용해 **속력은 그대로**, 방향만 바꿔요.\n크기 **C = 2vΩ sin φ**: 속력이 빠를수록, 고위도일수록 크고 적도에서 0\n푸코 진자의 진동면은 1시간에 **15° × sin φ** 돌아요(북반구 시계 방향).",
      "inquiry": "원판이 시계 반대 방향(북반구)으로 돌 때, 원판 위 종이에 남는 구슬 자국은 어떻게 될까요?\n시계 반대 방향(북반구) 원판에서 자국이 오른쪽으로 휘는 것을 확인해 보세요.\n시계 방향(남반구) 원판에서 자국이 왼쪽으로 휘는 것을 확인해 보세요.",
      "added": "2026-10-27",
      "updated": "2026-10-27"
