      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **위도**, **등압선 간격**, **기압 경도** 슬라이더를 움직여요.\n**① 지균풍·지상풍**, **② 경도풍**, **③ 일기도 판독**, **상층 (마찰 없음)**, **지상·해양**, **지상·육지**, **▶ 공기 덩어리 놓기**, **남반구로** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
      "concept": "**지균풍**(상층): 기압 경도력 = 전향력 → 등압선과 나란히, 북반구에서 저기압이 왼쪽\n지균풍 풍속 v = ΔP / (ρ · 2Ω sin φ · Δx): 등압선 간격이 좁을수록, 저위도일수록 빨라요.\n**경도풍**: 원형 등압선에서 기압 경도력과 전향력의 차가 **구심력** → 고기압성은 지균풍보다 빠르고, 저기압성은 느려요.\n**지상풍**: 마찰력 때문에 등압선을 비스듬히 가로질러 저기압 쪽으로 불어요(해양 약 10~20°, 육지 약 20~45°).",
      "inquiry": "북반구 상층에서 정지한 공기 덩어리를 기압 차 속에 놓으면, 결국 바람은 어떻게 불게 될까요?\n상층에서 공기 덩어리를 놓아 지균풍이 되는 것을 확인해 보세요.\n육지의 지상풍이 등압선을 비스듬히 가로지르는 것을 확인해 보세요.",
