      "concept": "마찰력의 영향을 받는 높이까지를 **대기 경계층**(보통 약 1 km), 그 위를 **자유 대기**라고 해요.\n지표면이 **거칠수록** 대기 경계층이 높아지고 지상 풍속이 약해져요.\n경계층에서는 높이 올라갈수록 **풍속이 빨라지고**, 풍향은 북반구에서 **시계 방향**으로 변해요.\n자유 대기에서는 등압선과 **나란히** 불어요(지균풍·경도풍).\n높이별 바람 화살표의 끝을 이으면 나선 → **에크만 나선** (해수의 에크만 나선과 같은 원리)",
      "inquiry": "북반구 대기 경계층에서 높이 올라갈수록 풍향은 어떻게 변할까요?\n지상(50 m 이하)과 자유 대기의 풍향·풍속을 모두 관측해 보세요.\n지표면을 도시·산지로 바꿔 대기 경계층이 어떻게 달라지는지 확인해 보세요.",
