      "concept": "**해들리 순환**(0~30°): 적도에서 상승 → 30° 부근 하강(아열대 고압대) → 지상 **무역풍**\n**페렐 순환**(30~60°): 두 순환 사이에서 간접적으로 생겨요 → 지상 **편서풍**\n**극순환**(60~90°): 극에서 하강 → 지상 **극동풍** → 60° 부근 **한대 전선대**\n적도 저압대는 상승 기류로 비가 많고, 30° 부근 고압대는 하강 기류로 건조해 **사막**이 많아요.\n자전이 없으면 전향력이 없어 반구마다 하나의 커다란 세포(**단일 세포**)가 생겨요.",
