      "concept": "안쪽(얼음) = **고위도**, 중간 = **중위도**, 바깥쪽(가열) = **저위도**\n**회전하지 않을 때**: 바깥에서 데워진 물이 상승해 표면에서 안쪽으로 이동하고, 안쪽에서 냉각되어 하강해요(단순한 대류).\n**회전할 때**: 온도 차에 의한 대류와 회전 효과가 합쳐져 서→동으로 도는 흐름이 **구불구불한 파동**을 이뤄요.\n회전이 빠를수록 파동의 수가 늘어나요. 파동이 남북으로 굽이치며 열을 고위도로 날라요.",
