      "status": "ready",
      "height": 0,
      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **파동의 수**, **파동의 진폭** 슬라이더를 움직여요.\n**① 파동의 일생**, **② 기압골과 지상**, **③ 제트류와 계절**, **⏸ 멈춤**, **1단계**, **2단계**, **3단계**, **4단계** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
      "concept": "중위도 상층 편서풍은 파장 약 10000 km 이상의 **행성파**로 남북으로 굽이쳐요.\n남북 기온 차가 커지면 파동이 발달하고, 찬 공기·따뜻한 공기가 떨어져 나가며 **열을 고위도로** 날라요.\n고위도 쪽으로 올라간 곳 = **기압 마루**(빠름), 저위도 쪽으로 내려온 곳 = **기압골**(느림)\n기압골 **서쪽** 상층 수렴 → 하강 → 지상 **고기압** / 기압골 **동쪽** 상층 발산 → 상승 → 지상 **저기압**\n**제트류**: 편서풍 중 좁고 강한 흐름. 남북 기온 차가 큰 **겨울**에 강해지고 남쪽으로 내려와요.",
      "inquiry": "상층 편서풍 파동의 기압골 동쪽 지상에는 어떤 기압이 발달할까요?\n① 4단계에서 찬 공기와 따뜻한 공기가 떨어져 나가는 것을 확인해 보세요.\n② 에서 진폭을 크게 키워 마루와 골의 풍속 차를 관찰해 보세요.",
